-- Slow: scalar UDF per row
SELECT CustomerID, dbo.fn_DiscountTier(CustomerID) AS Tier FROM Customer;

-- Fast: inline TVF, inlined into the plan
CREATE FUNCTION dbo.itvf_DiscountTier(@CustomerID INT)
RETURNS TABLE AS RETURN (
  SELECT CASE WHEN LifetimeSpend > 10000 THEN 'Gold' WHEN LifetimeSpend > 2000 THEN 'Silver' ELSE 'Bronze' END AS Tier
  FROM Customer WHERE CustomerID = @CustomerID
);
SELECT c.CustomerID, t.Tier FROM Customer c CROSS APPLY dbo.itvf_DiscountTier(c.CustomerID) t;

CREATE TRIGGER trg_CustomerSummary_Update ON vw_CustomerSummary
INSTEAD OF UPDATE AS
BEGIN
  UPDATE c SET c.Name = i.Name FROM Customer c JOIN inserted i ON c.CustomerID = i.CustomerID;
  UPDATE a SET a.City = i.City FROM Address a JOIN inserted i ON a.CustomerID = i.CustomerID;
END;

-- Snowflake with QUALIFY
SELECT * FROM Orders QUALIFY ROW_NUMBER() OVER (PARTITION BY CustomerID ORDER BY OrderDate DESC) = 1;

-- T-SQL equivalent
WITH Ranked AS (
  SELECT *, ROW_NUMBER() OVER (PARTITION BY CustomerID ORDER BY OrderDate DESC) AS RowNum FROM Orders
)
SELECT * FROM Ranked WHERE RowNum = 1;

-- T-SQL
SELECT * FROM Orders ORDER BY OrderDate, OrderID OFFSET 20 ROWS FETCH NEXT 10 ROWS ONLY;

-- Snowflake / Postgres
SELECT * FROM orders ORDER BY order_date, order_id LIMIT 10 OFFSET 20;

-- Classic Oracle
SELECT * FROM (SELECT o.*, ROWNUM rn FROM (SELECT * FROM orders ORDER BY order_date, order_id) o) WHERE rn BETWEEN 21 AND 30;

-- Query a table's state before it was dropped
SELECT * FROM my_table AT (TIMESTAMP => '2026-11-11 09:00:00'::timestamp);

-- Restore a dropped table within the retention window
UNDROP TABLE my_table;

-- Check current retention setting
SHOW PARAMETERS LIKE 'DATA_RETENTION_TIME_IN_DAYS' IN TABLE my_table;

SELECT Region, [Jan], [Feb], [Mar]
FROM (SELECT Region, Month, SalesAmount FROM Sales) AS Source
PIVOT (SUM(SalesAmount) FOR Month IN ([Jan], [Feb], [Mar])) AS Pvt;

CREATE PROCEDURE dbo.TransferFunds (@FromAccount INT, @ToAccount INT, @Amount DECIMAL(10,2)) AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;
    UPDATE Account SET Balance = Balance - @Amount WHERE AccountID = @FromAccount;
    UPDATE Account SET Balance = Balance + @Amount WHERE AccountID = @ToAccount;
    COMMIT TRANSACTION;
  END TRY
  BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
  END CATCH
END;

CREATE TYPE dbo.PriceUpdateType AS TABLE (ProductID INT PRIMARY KEY, NewPrice DECIMAL(10,2));

CREATE PROCEDURE dbo.BulkUpdatePrices (@PriceUpdates dbo.PriceUpdateType READONLY) AS
BEGIN
  MERGE INTO Product AS target
  USING @PriceUpdates AS source ON target.ProductID = source.ProductID
  WHEN MATCHED THEN UPDATE SET target.Price = source.NewPrice
  WHEN NOT MATCHED THEN INSERT (ProductID, Price) VALUES (source.ProductID, source.NewPrice);
END;

COPY INTO my_table
